           valor[AJ_DTS_AC3]);
  }
#else
  (void)viuDtsTpk; (void)dtsSaidaAntiga; (void)dtsModoAntigo;
#endif
  if (!viuFoco && focoAntigo >= 0) {
    valor[AJ_FOCO_TRAILER] = focoTrailerMigrar(focoAntigo);
