  if (valor[AJ_IDIOMA] == 0 && viuIdioma) idiomaEfetivo = idiomaGravado;
  // #509: "Som do trailer na pagina do titulo" virou o UNICO "Som do trailer".
  // Quem tinha som na pagina mantem o som: o ajuste unico herda a escolha (uma
