    if (m) fclose(m);
    else {
      char *resp = dados_ler("telemetria-perguntado.txt");
      int disseNao = resp && resp[0] == '0';
      free(resp);
      if (!disseNao && valor[AJ_ENVIO_AUTO] != 0) {
        valor[AJ_ENVIO_AUTO] = 0;
        printf("[ajustes] envio automatico religado (migracao unica do #149)\n");
