#if (defined(__EMSCRIPTEN__) || defined(NV_TPK)) && !defined(NV_TRAILER_AUTO_TIZEN)
  // MIGRACAO UNICA (1.3.10): o .wgt da 1.3.9 saiu de uma build com
  // NV_TRAILER_AUTO_TIZEN (a das fotos das notas), entao na Samsung o
